final:
class Bad:
    n: int

def check(x: int) -> int fail Bad:
    """Return x when it is even, otherwise fail with Bad carrying x."""
    ex check(4) == 4
    ex check(3) == Err(Bad(n=3))
    if x % 2 == 1:
        fail Bad(n=x)
    return x

def all_even(xs: list[int]) -> list[int] fail Bad:
    """Check every element in parallel. Return xs when all are even, otherwise fail with the Bad of the lowest-index odd element, regardless of completion order."""
    post out.len() == xs.len()
    ex all_even([2, 4]) == [2, 4]
    ex all_even([4, 1, 3]) == Err(Bad(n=1))
    flags: list[int] = par [check(x) else -1 for x in xs]
    for i in range(xs.len()):
        if flags[i] == -1:
            fail Bad(n=xs[i])
    return xs.copy()
